		ArrayList<MProphetData> peptideData=new ArrayList<MProphetData>();
		
		int backgroundToAdd = 10;
		int targetsToAdd = 100; 
		int decoysToAdd = backgroundToAdd + targetsToAdd;  // the number of decoys should match the number of total peptides
		
		ArrayList<MProphetData> subsetBackground = new ArrayList<>(backgroundData.subList(0, Math.min(backgroundToAdd, backgroundData.size())));
		ArrayList<MProphetData> subsetTarget = new ArrayList<>(targetData.subList(0, Math.min(targetsToAdd, targetData.size())));
		ArrayList<MProphetData> subsetDecoy = new ArrayList<>(decoyData.subList(0, Math.min(decoysToAdd, decoyData.size())));

		ArrayList<MProphetData> combinedData = new ArrayList<>(peptideData);
		combinedData.addAll(subsetBackground);
		combinedData.addAll(subsetTarget);
		combinedData.addAll(subsetDecoy);
		
		ArrayList<String> featureNames=new ArrayList<String>();
		featureNames.add("main_var_Intensity");
		featureNames.add("var_Shape_(weighted)");
		featureNames.add("var_Co-elution_(weighted)");
		featureNames.add("var_Co-elution_count");
		featureNames.add("var_Signal_to_noise");
		featureNames.add("var_Precursor_mass_error");
		featureNames.add("var_Precursor_isotope_dot_product");
		
		int startingScoreIndex=0;
		
	//	MProphetDataset dataset=new MProphetDataset(featureNames, startingScoreIndex, peptideData);
		MProphetDataset dataset=new MProphetDataset(featureNames, startingScoreIndex, combinedData);

		
		int seed=1;
		
		SearchParameters params=SearchParameterParser.getDefaultParametersObject();
		
		MProphetExecutionData mockData=new MProphetExecutionData(File.createTempFile("inputTSV", ".temp"), 
				File.createTempFile("fastaFile", ".temp"), 
				File.createTempFile("peptideOutputFile", ".temp"), 
				File.createTempFile("peptideDecoyFile", ".temp"), 
				params);
		
		MProphetReiter mprophet=new MProphetReiter(mockData, params.getPercolatorThreshold(), seed, params.getAAConstants());
		MProphetResult result=mprophet.calculateProbabilities(dataset, seed);
		assertNotNull(result);
		//assertTrue(result.getPassingPeptides().size()>100);
